INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('6ecbde73-ff12-48d3-a47e-17dc4b186866', 'general_lines', NULL, 'What is moral hazard?', '¿Qué es el riesgo moral?', '["Unethical behavior by agents", "Increased risk-taking because insurance covers the loss", "A physical hazard", "A premium calculation"]', '["Comportamiento poco ético de agentes", "Mayor toma de riesgos porque el seguro cubre la pérdida", "Un peligro físico", "Un cálculo de prima"]', 1, 'Moral hazard is the tendency for people to take greater risks or be less careful because they have insurance to cover potential losses.', 'El riesgo moral es la tendencia de las personas a tomar mayores riesgos o ser menos cuidadosos porque tienen seguro para cubrir pérdidas potenciales.', true, '2026-01-14 23:23:20.925166', '2026-01-14 23:23:20.925166') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('707bfcf2-95a0-48c8-8661-2b0b8db6eb3e', 'general_lines', NULL, 'What is the duty to defend in liability insurance?', '¿Qué es el deber de defender en el seguro de responsabilidad?', '["The insured''s obligation to fight claims", "The insurer''s obligation to provide legal defense for covered claims", "The agent''s duty", "A premium requirement"]', '["La obligación del asegurado de combatir reclamos", "La obligación del asegurador de proporcionar defensa legal para reclamos cubiertos", "El deber del agente", "Un requisito de prima"]', 1, 'The duty to defend is the insurer''s contractual obligation to provide legal defense for the insured when a covered claim or lawsuit is filed.', 'El deber de defender es la obligación contractual del asegurador de proporcionar defensa legal para el asegurado cuando se presenta un reclamo o demanda cubierta.', true, '2026-01-14 23:13:37.26766', '2026-01-14 23:13:37.26766') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7194be7a-c581-47ee-b4ca-859504592160', 'general_lines', NULL, 'What is professional liability insurance also known as?', '¿Cómo se conoce también el seguro de responsabilidad profesional?', '["General liability", "Errors and Omissions (E&O) insurance", "Workers compensation", "Product liability"]', '["Responsabilidad general", "Seguro de Errores y Omisiones (E&O)", "Compensación de trabajadores", "Responsabilidad por productos"]', 1, 'Professional liability insurance is commonly called Errors and Omissions (E&O) insurance and covers professionals against negligence claims.', 'El seguro de responsabilidad profesional se conoce comúnmente como seguro de Errores y Omisiones (E&O) y cubre a los profesionales contra reclamos de negligencia.', true, '2026-01-14 23:10:18.118143', '2026-01-14 23:10:18.118143') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('721473e1-1073-4511-a319-dcbb474e9d76', 'general_lines', NULL, 'What is a retrospective rating plan?', '¿Qué es un plan de tarificación retrospectiva?', '["A fixed premium plan", "A plan where final premium is adjusted based on actual loss experience during the policy period", "A discount plan", "A life insurance plan"]', '["Un plan de prima fija", "Un plan donde la prima final se ajusta basada en la experiencia real de pérdidas durante el período de la póliza", "Un plan de descuento", "Un plan de seguro de vida"]', 1, 'A retrospective rating plan adjusts the final premium based on the insured''s actual loss experience during the policy period, within minimum and maximum limits.', 'Un plan de tarificación retrospectiva ajusta la prima final basada en la experiencia real de pérdidas del asegurado durante el período de la póliza, dentro de límites mínimos y máximos.', true, '2026-01-14 23:23:20.949051', '2026-01-14 23:23:20.949051') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('74e77e04-c489-4faf-bbcc-6477739a1940', 'general_lines', NULL, 'What is twisting in insurance?', '¿Qué es el twisting en seguros?', '["Misrepresenting facts to induce a customer to replace an existing policy", "A type of coverage", "A premium discount", "A policy endorsement"]', '["Tergiversar hechos para inducir a un cliente a reemplazar una póliza existente", "Un tipo de cobertura", "Un descuento de prima", "Un endoso de póliza"]', 0, 'Twisting is the illegal practice of using misrepresentations to convince a policyholder to replace an existing policy with a new one.', 'El twisting es la práctica ilegal de usar tergiversaciones para convencer a un asegurado de reemplazar una póliza existente con una nueva.', true, '2026-01-14 18:28:35.690628', '2026-01-14 18:28:35.690628') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('75d06899-6aa5-448e-932e-8d7ddcc77ef8', 'general_lines', NULL, 'What is the cancellation provision in a policy?', '¿Qué es la disposición de cancelación en una póliza?', '["A coverage provision", "Terms explaining how either party may cancel the policy", "A premium calculation", "An exclusion"]', '["Una disposición de cobertura", "Términos que explican cómo cualquiera de las partes puede cancelar la póliza", "Un cálculo de prima", "Una exclusión"]', 1, 'The cancellation provision specifies the conditions and procedures under which the insurer or insured may cancel the policy before expiration.', 'La disposición de cancelación especifica las condiciones y procedimientos bajo los cuales el asegurador o asegurado puede cancelar la póliza antes del vencimiento.', true, '2026-01-14 23:23:21.024229', '2026-01-14 23:23:21.024229') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('767b3a96-fc2f-4ba4-a06d-2819f5b500cf', 'general_lines', NULL, 'What is the purpose of a blanket policy?', '¿Cuál es el propósito de una póliza general?', '["To cover only one item", "To cover multiple locations or types of property under a single limit", "To exclude coverage", "To provide life insurance"]', '["Cubrir solo un artículo", "Cubrir múltiples ubicaciones o tipos de propiedad bajo un solo límite", "Excluir cobertura", "Proporcionar seguro de vida"]', 1, 'A blanket policy covers multiple properties, locations, or types of property under a single coverage limit.', 'Una póliza general cubre múltiples propiedades, ubicaciones o tipos de propiedad bajo un solo límite de cobertura.', true, '2026-01-14 23:10:18.158709', '2026-01-14 23:10:18.158709') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('76ddf552-d5e3-4297-b333-bb8a6c9f7436', 'general_lines', NULL, 'What is garagekeepers coverage?', '¿Qué es la cobertura de cuidador de garaje?', '["Coverage for garage buildings", "Coverage for damage to customers'' vehicles in the care of an auto service business", "Liability coverage", "Life insurance"]', '["Cobertura para edificios de garaje", "Cobertura por daños a vehículos de clientes bajo el cuidado de un negocio de servicio de autos", "Cobertura de responsabilidad", "Seguro de vida"]', 1, 'Garagekeepers coverage protects auto dealers and repair shops for damage to customers'' vehicles left in their care, custody, or control.', 'La cobertura de cuidador de garaje protege a concesionarios de autos y talleres de reparación por daños a vehículos de clientes dejados bajo su cuidado, custodia o control.', true, '2026-01-14 23:16:55.557753', '2026-01-14 23:16:55.557753') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('794e5628-9253-421f-96fc-6851b512ea9f', 'general_lines', NULL, 'What is adverse selection in insurance?', '¿Qué es la selección adversa en seguros?', '["Choosing the best risks", "The tendency for higher-risk individuals to seek more insurance coverage", "Selecting good agents", "Choosing low premiums"]', '["Elegir los mejores riesgos", "La tendencia de individuos de alto riesgo a buscar más cobertura de seguro", "Seleccionar buenos agentes", "Elegir primas bajas"]', 1, 'Adverse selection occurs when people with higher risks are more likely to purchase insurance, potentially leading to higher claims than expected.', 'La selección adversa ocurre cuando las personas con mayores riesgos tienen más probabilidades de comprar seguros, potencialmente llevando a reclamos más altos de lo esperado.', true, '2026-01-14 23:23:20.919871', '2026-01-14 23:23:20.919871') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7a1a3d21-303a-428b-82fb-aa01e8a00292', 'general_lines', NULL, 'What is the purpose of a commercial property policy?', '¿Cuál es el propósito de una póliza de propiedad comercial?', '["To cover employee injuries", "To protect business property from physical damage", "To provide life insurance", "To cover auto accidents"]', '["Cubrir lesiones de empleados", "Proteger la propiedad comercial de daños físicos", "Proporcionar seguro de vida", "Cubrir accidentes de auto"]', 1, 'A commercial property policy protects business property, including buildings, equipment, and inventory, from covered perils.', 'Una póliza de propiedad comercial protege la propiedad comercial, incluyendo edificios, equipos e inventario, de riesgos cubiertos.', true, '2026-01-14 23:13:37.238559', '2026-01-14 23:13:37.238559') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7b881036-503b-42a6-b4f6-1c53cd8dc21e', 'general_lines', NULL, 'What is a performance bond?', '¿Qué es una fianza de cumplimiento?', '["Insurance for actors", "A guarantee that a contractor will complete a project according to specifications", "A type of life insurance", "Health coverage"]', '["Seguro para actores", "Una garantía de que un contratista completará un proyecto según las especificaciones", "Un tipo de seguro de vida", "Cobertura de salud"]', 1, 'A performance bond guarantees that a contractor will complete a project according to the contract terms and specifications.', 'Una fianza de cumplimiento garantiza que un contratista completará un proyecto según los términos del contrato y las especificaciones.', true, '2026-01-14 23:10:18.148445', '2026-01-14 23:10:18.148445') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('7c701ba5-1db0-47f0-921d-036f45637872', 'general_lines', NULL, 'What is fire legal liability coverage?', '¿Qué es la cobertura de responsabilidad legal por incendio?', '["Coverage for the insured''s property", "Coverage for damage to rented premises caused by fire", "Auto coverage", "Life insurance"]', '["Cobertura para la propiedad del asegurado", "Cobertura por daños a instalaciones alquiladas causados por incendio", "Cobertura de auto", "Seguro de vida"]', 1, 'Fire legal liability (damage to premises rented to you) coverage pays for fire damage to premises the insured rents or temporarily occupies.', 'La cobertura de responsabilidad legal por incendio (daños a instalaciones alquiladas) paga por daños por incendio a instalaciones que el asegurado alquila u ocupa temporalmente.', true, '2026-01-14 23:16:55.35124', '2026-01-14 23:16:55.35124') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('80463efc-9438-45b3-919a-b3dd7b188e17', 'general_lines', NULL, 'What is the purpose of a reservation of rights letter?', '¿Cuál es el propósito de una carta de reserva de derechos?', '["To accept a claim", "To notify the insured that the insurer is investigating coverage while defending the claim", "To cancel the policy", "To increase premiums"]', '["Aceptar un reclamo", "Notificar al asegurado que el asegurador está investigando la cobertura mientras defiende el reclamo", "Cancelar la póliza", "Aumentar las primas"]', 1, 'A reservation of rights letter notifies the insured that the insurer is providing a defense but reserves the right to later deny coverage based on policy terms.', 'Una carta de reserva de derechos notifica al asegurado que el asegurador está proporcionando una defensa pero se reserva el derecho de luego denegar la cobertura basándose en los términos de la póliza.', true, '2026-01-14 23:13:37.295726', '2026-01-14 23:13:37.295726') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8329eb85-b086-41a3-bb89-ae1b683fb439', 'general_lines', NULL, 'What is a floater policy?', '¿Qué es una póliza flotante?', '["A policy that covers only water damage", "A policy that covers movable property at various locations", "A life insurance policy", "An auto policy"]', '["Una póliza que solo cubre daños por agua", "Una póliza que cubre propiedad móvil en varias ubicaciones", "Una póliza de seguro de vida", "Una póliza de auto"]', 1, 'A floater policy provides coverage for movable property that travels to different locations, such as jewelry, fine art, or contractor equipment.', 'Una póliza flotante proporciona cobertura para propiedad móvil que viaja a diferentes ubicaciones, como joyas, arte fino o equipo de contratistas.', true, '2026-01-14 23:10:18.240223', '2026-01-14 23:10:18.240223') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8737f97f-3d61-4b64-949b-cb5a0c0acc1f', 'general_lines', NULL, 'What is the examination under oath provision?', '¿Qué es la disposición de examen bajo juramento?', '["A court trial", "A policy provision allowing the insurer to require sworn testimony from the insured about a claim", "A premium calculation", "An exclusion"]', '["Un juicio en tribunal", "Una disposición de póliza que permite al asegurador requerir testimonio jurado del asegurado sobre un reclamo", "Un cálculo de prima", "Una exclusión"]', 1, 'The examination under oath provision allows the insurer to require the insured to provide sworn testimony about a claim, typically recorded by a court reporter.', 'La disposición de examen bajo juramento permite al asegurador requerir que el asegurado proporcione testimonio jurado sobre un reclamo, típicamente registrado por un taquígrafo judicial.', true, '2026-01-14 23:23:21.003149', '2026-01-14 23:23:21.003149') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('88c842c6-d58e-4692-9f9f-b7e45abf9a20', 'general_lines', NULL, 'What is treaty reinsurance?', '¿Qué es el reaseguro por tratado?', '["Case-by-case reinsurance", "An agreement where the reinsurer automatically accepts a portion of specified business", "International reinsurance only", "Property reinsurance only"]', '["Reaseguro caso por caso", "Un acuerdo donde el reasegurador automáticamente acepta una porción del negocio especificado", "Solo reaseguro internacional", "Solo reaseguro de propiedad"]', 1, 'Treaty reinsurance is an ongoing agreement where the reinsurer automatically accepts a defined share of the ceding company''s specified business.', 'El reaseguro por tratado es un acuerdo continuo donde el reasegurador automáticamente acepta una participación definida del negocio especificado de la compañía cedente.', true, '2026-01-14 23:13:37.36985', '2026-01-14 23:13:37.36985') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8ace3fdd-1e23-4323-b4cf-2cc6fb46e442', 'general_lines', NULL, 'What is churning in insurance?', '¿Qué es el churning en seguros?', '["Excessive replacement of policies primarily to generate commissions", "A type of coverage", "A premium payment method", "A policy endorsement"]', '["Reemplazo excesivo de pólizas principalmente para generar comisiones", "Un tipo de cobertura", "Un método de pago de prima", "Un endoso de póliza"]', 0, 'Churning is the unethical practice of replacing policies excessively to earn additional commissions at the expense of the policyholder.', 'El churning es la práctica no ética de reemplazar pólizas excesivamente para ganar comisiones adicionales a expensas del asegurado.', true, '2026-01-14 18:28:35.694373', '2026-01-14 18:28:35.694373') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8b1cf63f-6966-4b4f-8ffb-340c07ab4307', 'general_lines', NULL, 'What is the difference between burglary and robbery?', '¿Cuál es la diferencia entre allanamiento y robo?', '["No difference", "Burglary involves forced entry; robbery involves force or threat against a person", "Robbery requires forced entry", "Burglary requires a weapon"]', '["Sin diferencia", "El allanamiento involucra entrada forzada; el robo involucra fuerza o amenaza contra una persona", "El robo requiere entrada forzada", "El allanamiento requiere un arma"]', 1, 'Burglary involves unlawful entry with visible signs of forced entry, while robbery involves taking property by force, violence, or threat against a person.', 'El allanamiento involucra entrada ilegal con signos visibles de entrada forzada, mientras que el robo involucra tomar propiedad por fuerza, violencia o amenaza contra una persona.', true, '2026-01-14 23:16:55.382731', '2026-01-14 23:16:55.382731') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8bb114b3-998e-4d72-82bc-1aa0e43dfec6', 'general_lines', NULL, 'What is a combined ratio in insurance?', '¿Qué es un índice combinado en seguros?', '["A premium calculation", "The sum of loss ratio and expense ratio measuring overall profitability", "A claims calculation", "A coverage calculation"]', '["Un cálculo de prima", "La suma del índice de pérdidas y el índice de gastos midiendo la rentabilidad general", "Un cálculo de reclamos", "Un cálculo de cobertura"]', 1, 'The combined ratio adds the loss ratio and expense ratio to measure underwriting profitability; a ratio under 100% indicates underwriting profit.', 'El índice combinado suma el índice de pérdidas y el índice de gastos para medir la rentabilidad de suscripción; un índice bajo 100% indica ganancia de suscripción.', true, '2026-01-14 23:16:55.589783', '2026-01-14 23:16:55.589783') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8bcc4071-b916-4ea9-a873-d1e7e568fd15', 'general_lines', NULL, 'What is the adhesion characteristic of insurance contracts?', '¿Qué es la característica de adhesión de los contratos de seguro?', '["Negotiated equally", "One party drafts the contract and the other must accept or reject it as written", "Both parties write the contract", "No standard forms are used"]', '["Negociado igualmente", "Una parte redacta el contrato y la otra debe aceptarlo o rechazarlo como está escrito", "Ambas partes escriben el contrato", "No se usan formularios estándar"]', 1, 'Insurance contracts are contracts of adhesion, meaning the insurer drafts the contract and the insured must accept or reject it without negotiation of terms.', 'Los contratos de seguro son contratos de adhesión, lo que significa que el asegurador redacta el contrato y el asegurado debe aceptarlo o rechazarlo sin negociación de términos.', true, '2026-01-14 23:13:37.346098', '2026-01-14 23:13:37.346098') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8d99f95c-745e-421a-9c15-8143cc038b31', 'general_lines', NULL, 'What is a lost instrument bond?', '¿Qué es una fianza de instrumento perdido?', '["A musical instrument bond", "A bond protecting against claims from a lost negotiable instrument like a stock certificate", "A court bond", "A fidelity bond"]', '["Una fianza de instrumento musical", "Una fianza que protege contra reclamos de un instrumento negociable perdido como un certificado de acciones", "Una fianza judicial", "Una fianza de fidelidad"]', 1, 'A lost instrument bond protects an issuer when replacing lost, stolen, or destroyed negotiable instruments like stock certificates or bonds.', 'Una fianza de instrumento perdido protege a un emisor al reemplazar instrumentos negociables perdidos, robados o destruidos como certificados de acciones o bonos.', true, '2026-01-14 23:16:55.520802', '2026-01-14 23:16:55.520802') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('8dc49b8c-3e11-41ea-a1d1-269685ebb7ca', 'general_lines', NULL, 'What is the proximate cause of loss?', '¿Qué es la causa próxima de pérdida?', '["The last cause in a chain of events", "The primary cause that sets in motion an unbroken chain of events leading to a loss", "Any cause of loss", "An excluded cause"]', '["La última causa en una cadena de eventos", "La causa primaria que pone en movimiento una cadena ininterrumpida de eventos que llevan a una pérdida", "Cualquier causa de pérdida", "Una causa excluida"]', 1, 'Proximate cause is the primary cause that initiates an unbroken chain of events leading to a loss, used to determine coverage.', 'La causa próxima es la causa primaria que inicia una cadena ininterrumpida de eventos que llevan a una pérdida, utilizada para determinar la cobertura.', true, '2026-01-14 23:13:37.324192', '2026-01-14 23:13:37.324192') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9011f0ab-19f3-46fd-b326-be4022b5a7b7', 'general_lines', NULL, 'What is a risk management program?', '¿Qué es un programa de gestión de riesgos?', '["Only purchasing insurance", "A systematic approach to identifying, analyzing, and controlling risks", "Avoiding all activities", "Only transferring risk"]', '["Solo comprar seguro", "Un enfoque sistemático para identificar, analizar y controlar riesgos", "Evitar todas las actividades", "Solo transferir riesgos"]', 1, 'A risk management program is a comprehensive approach that identifies exposures, analyzes risks, selects appropriate techniques, and monitors results.', 'Un programa de gestión de riesgos es un enfoque integral que identifica exposiciones, analiza riesgos, selecciona técnicas apropiadas y monitorea resultados.', true, '2026-01-14 23:23:20.965627', '2026-01-14 23:23:20.965627') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9140a392-ddf8-43e5-88f3-4ee7fb3a8d47', 'general_lines', NULL, 'What is MCS-90 endorsement?', '¿Qué es el endoso MCS-90?', '["A property endorsement", "A federal endorsement requiring interstate motor carriers to provide minimum liability coverage", "A life insurance endorsement", "A health endorsement"]', '["Un endoso de propiedad", "Un endoso federal que requiere que los transportistas interestatales proporcionen cobertura de responsabilidad mínima", "Un endoso de seguro de vida", "Un endoso de salud"]', 1, 'MCS-90 is a federal endorsement that ensures interstate trucking companies maintain minimum liability coverage required by the Department of Transportation.', 'MCS-90 es un endoso federal que asegura que las compañías de camiones interestatales mantengan la cobertura de responsabilidad mínima requerida por el Departamento de Transporte.', true, '2026-01-14 23:16:55.554133', '2026-01-14 23:16:55.554133') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('92a291a6-a6a6-4051-8446-4de717c9b4ac', 'general_lines', NULL, 'What is rebating in insurance?', '¿Qué es el rebating en seguros?', '["Returning part of the premium or commission as an inducement to buy insurance", "A type of coverage", "A premium increase", "A policy endorsement"]', '["Devolver parte de la prima o comisión como incentivo para comprar seguro", "Un tipo de cobertura", "Un aumento de prima", "Un endoso de póliza"]', 0, 'Rebating is the illegal practice of offering something of value not specified in the policy to induce someone to purchase insurance.', 'El rebating es la práctica ilegal de ofrecer algo de valor no especificado en la póliza para inducir a alguien a comprar seguro.', true, '2026-01-14 18:28:35.697228', '2026-01-14 18:28:35.697228') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('93e3f65f-dbb6-42fe-8c06-cc89e8c0c5c5', 'general_lines', NULL, 'What is valuable papers coverage?', '¿Qué es la cobertura de documentos valiosos?', '["Coverage for currency", "Coverage for the cost to research, replace, or restore important documents", "Life insurance", "Auto coverage"]', '["Cobertura para moneda", "Cobertura para el costo de investigar, reemplazar o restaurar documentos importantes", "Seguro de vida", "Cobertura de auto"]', 1, 'Valuable papers coverage pays for the cost to research, replace, or restore valuable documents and records that are damaged or destroyed.', 'La cobertura de documentos valiosos paga por el costo de investigar, reemplazar o restaurar documentos y registros valiosos que son dañados o destruidos.', true, '2026-01-14 23:16:55.46294', '2026-01-14 23:16:55.46294') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('945f9a45-3b51-44fc-bdd2-4f9dee04b1e1', 'general_lines', NULL, 'What is equipment breakdown insurance (formerly boiler and machinery)?', '¿Qué es el seguro de avería de equipos (anteriormente calderas y maquinaria)?', '["Coverage for manual tools only", "Coverage for mechanical and electrical equipment failures", "Auto coverage", "Life insurance"]', '["Cobertura solo para herramientas manuales", "Cobertura para fallas de equipos mecánicos y eléctricos", "Cobertura de auto", "Seguro de vida"]', 1, 'Equipment breakdown insurance covers losses from the sudden and accidental breakdown of mechanical, electrical, and pressure equipment.', 'El seguro de avería de equipos cubre pérdidas por la avería repentina y accidental de equipos mecánicos, eléctricos y de presión.', true, '2026-01-14 23:10:18.213645', '2026-01-14 23:10:18.213645') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('94826d80-eae3-4bcc-ab4e-e1cd8e426fe3', 'general_lines', NULL, 'What is the Texas Department of Insurance (TDI)?', '¿Qué es el Departamento de Seguros de Texas (TDI)?', '["A private insurance company", "The state agency that regulates the insurance industry in Texas", "A federal agency", "An insurance trade association"]', '["Una compañía de seguros privada", "La agencia estatal que regula la industria de seguros en Texas", "Una agencia federal", "Una asociación comercial de seguros"]', 1, 'TDI is the Texas state agency responsible for regulating the insurance industry, licensing agents, and protecting consumers.', 'TDI es la agencia estatal de Texas responsable de regular la industria de seguros, licenciar agentes y proteger a los consumidores.', true, '2026-01-14 23:13:37.276246', '2026-01-14 23:13:37.276246') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('957ad9aa-81cc-42db-903a-caf2227d5d91', 'general_lines', NULL, 'What is the purpose of a binder in insurance?', '¿Cuál es el propósito de un binder en seguros?', '["To permanently bind a policy", "To provide temporary evidence of coverage until the policy is issued", "To cancel coverage", "To increase premiums"]', '["Vincular permanentemente una póliza", "Proporcionar evidencia temporal de cobertura hasta que se emita la póliza", "Cancelar la cobertura", "Aumentar las primas"]', 1, 'A binder provides temporary evidence of insurance coverage until the formal policy is issued, allowing immediate protection for the insured.', 'Un binder proporciona evidencia temporal de cobertura de seguro hasta que se emita la póliza formal, permitiendo protección inmediata para el asegurado.', true, '2026-01-14 23:23:21.02087', '2026-01-14 23:23:21.02087') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('96cdfbec-80e5-42cf-beec-d85b74746e43', 'general_lines', NULL, 'What is extended reporting period coverage (tail coverage)?', '¿Qué es la cobertura de período de informe extendido (cobertura de cola)?', '["Coverage for property", "Coverage allowing claims to be reported after a claims-made policy expires", "Auto coverage", "Life insurance"]', '["Cobertura de propiedad", "Cobertura que permite que los reclamos se reporten después de que expire una póliza de reclamos hechos", "Cobertura de auto", "Seguro de vida"]', 1, 'Tail coverage extends the time period during which claims can be reported under a claims-made policy after the policy has expired.', 'La cobertura de cola extiende el período de tiempo durante el cual los reclamos pueden reportarse bajo una póliza de reclamos hechos después de que la póliza haya expirado.', true, '2026-01-14 23:10:18.230987', '2026-01-14 23:10:18.230987') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9a65b824-de22-4256-a35a-ec1bfa877e25', 'general_lines', NULL, 'What is the purpose of the ''other insurance'' clause?', '¿Cuál es el propósito de la cláusula de ''otro seguro''?', '["To eliminate coverage", "To determine how multiple policies covering the same loss will share payment", "To increase premiums", "To reduce deductibles"]', '["Eliminar cobertura", "Determinar cómo múltiples pólizas que cubren la misma pérdida compartirán el pago", "Aumentar las primas", "Reducir deducibles"]', 1, 'The other insurance clause establishes how claims will be handled when more than one policy covers the same loss.', 'La cláusula de otro seguro establece cómo se manejarán los reclamos cuando más de una póliza cubra la misma pérdida.', true, '2026-01-14 23:10:18.243341', '2026-01-14 23:10:18.243341') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9bf96d0d-76ba-4a51-a42d-028ffd38a9e7', 'general_lines', NULL, 'What is the products-completed operations aggregate limit?', '¿Qué es el límite agregado de productos-operaciones completadas?', '["A per claim limit", "The maximum the insurer will pay for all products and completed operations claims in a policy period", "A deductible", "The premium"]', '["Un límite por reclamo", "El máximo que el asegurador pagará por todos los reclamos de productos y operaciones completadas en un período de póliza", "Un deducible", "La prima"]', 1, 'The products-completed operations aggregate is the maximum the insurer will pay for all products liability and completed operations claims during a policy period.', 'El agregado de productos-operaciones completadas es el máximo que el asegurador pagará por todos los reclamos de responsabilidad por productos y operaciones completadas durante un período de póliza.', true, '2026-01-14 23:16:55.532159', '2026-01-14 23:16:55.532159') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9c8dfd32-2cf5-4664-8af4-496535a694b7', 'general_lines', NULL, 'What is the pollution exclusion in CGL policies?', '¿Qué es la exclusión de contaminación en las pólizas CGL?', '["Coverage for pollution", "An exclusion eliminating coverage for most pollution-related claims", "A premium surcharge", "An endorsement adding coverage"]', '["Cobertura para contaminación", "Una exclusión que elimina la cobertura para la mayoría de los reclamos relacionados con contaminación", "Un recargo de prima", "Un endoso que agrega cobertura"]', 1, 'The pollution exclusion eliminates coverage for bodily injury or property damage arising from the discharge, dispersal, or release of pollutants.', 'La exclusión de contaminación elimina la cobertura para lesiones corporales o daños a la propiedad que surgen de la descarga, dispersión o liberación de contaminantes.', true, '2026-01-14 23:13:37.389491', '2026-01-14 23:13:37.389491') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9ce2d06b-a3f1-4152-8487-9ae555a09762', 'general_lines', NULL, 'What is Protection and Indemnity (P&I) coverage?', '¿Qué es la cobertura de Protección e Indemnización (P&I)?', '["Property coverage", "Marine liability coverage for bodily injury, property damage, and pollution", "Cargo coverage", "Hull coverage"]', '["Cobertura de propiedad", "Cobertura de responsabilidad marítima para lesiones corporales, daños a la propiedad y contaminación", "Cobertura de carga", "Cobertura de casco"]', 1, 'P&I coverage provides liability protection for shipowners covering bodily injury, property damage, collision liability, and pollution.', 'La cobertura P&I proporciona protección de responsabilidad para propietarios de barcos cubriendo lesiones corporales, daños a la propiedad, responsabilidad por colisión y contaminación.', true, '2026-01-14 23:16:55.489072', '2026-01-14 23:16:55.489072') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('9d482eae-2401-45dd-b324-e287fd24e7f1', 'general_lines', NULL, 'What is the FAIR Plan?', '¿Qué es el Plan FAIR?', '["A discount program", "A program providing basic property insurance to those who cannot obtain coverage in the standard market", "A life insurance plan", "An auto insurance program"]', '["Un programa de descuento", "Un programa que proporciona seguro de propiedad básico a aquellos que no pueden obtener cobertura en el mercado estándar", "Un plan de seguro de vida", "Un programa de seguro de auto"]', 1, 'FAIR (Fair Access to Insurance Requirements) Plans are state-mandated programs that provide basic property insurance to property owners who cannot find coverage in the standard market.', 'Los Planes FAIR (Acceso Justo a Requisitos de Seguro) son programas mandados por el estado que proporcionan seguro de propiedad básico a propietarios que no pueden encontrar cobertura en el mercado estándar.', true, '2026-01-14 23:13:37.308011', '2026-01-14 23:13:37.308011') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a205b04a-63dd-45e4-b40b-e95024ecf9c6', 'general_lines', NULL, 'What does coinsurance mean in commercial property insurance?', '¿Qué significa el coaseguro en el seguro de propiedad comercial?', '["Two insurers share the risk equally", "The insured must insure property to a specified percentage of its value or face a penalty", "The premium is shared", "Coverage is automatic"]', '["Dos aseguradores comparten el riesgo por igual", "El asegurado debe asegurar la propiedad a un porcentaje especificado de su valor o enfrentar una penalidad", "La prima se comparte", "La cobertura es automática"]', 1, 'Coinsurance requires the insured to maintain coverage equal to a specified percentage of the property''s value (typically 80%) or face a reduced claim payment.', 'El coaseguro requiere que el asegurado mantenga cobertura igual a un porcentaje especificado del valor de la propiedad (típicamente 80%) o enfrente un pago de reclamo reducido.', true, '2026-01-14 23:10:18.139647', '2026-01-14 23:10:18.139647') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a2346ba7-868b-49aa-8f0a-ab7646a6988d', 'general_lines', NULL, 'What is pro rata cancellation?', '¿Qué es la cancelación prorrateada?', '["A penalty-based cancellation", "A cancellation where the return premium is calculated based on time remaining without penalty", "A full premium return", "A premium increase"]', '["Una cancelación basada en penalidad", "Una cancelación donde el reembolso de prima se calcula basado en el tiempo restante sin penalidad", "Un retorno de prima completo", "Un aumento de prima"]', 1, 'Pro rata cancellation returns the unearned premium based on the exact time remaining in the policy period, with no penalty deducted.', 'La cancelación prorrateada devuelve la prima no ganada basada en el tiempo exacto restante en el período de la póliza, sin penalidad deducida.', true, '2026-01-14 23:23:21.033357', '2026-01-14 23:23:21.033357') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a333e3e0-cd59-4571-8d2a-2a789cace869', 'general_lines', NULL, 'What is severity in risk analysis?', '¿Qué es la severidad en el análisis de riesgos?', '["How often losses occur", "The potential size or magnitude of losses when they occur", "The premium cost", "The deductible amount"]', '["Con qué frecuencia ocurren las pérdidas", "El tamaño potencial o magnitud de las pérdidas cuando ocurren", "El costo de la prima", "El monto del deducible"]', 1, 'Severity refers to the potential size or financial impact of losses when they occur, used to determine appropriate coverage limits.', 'La severidad se refiere al tamaño potencial o impacto financiero de las pérdidas cuando ocurren, utilizada para determinar límites de cobertura apropiados.', true, '2026-01-14 23:23:20.976636', '2026-01-14 23:23:20.976636') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a5c5891a-9ed3-423b-b45a-9b91d3d1d76e', 'general_lines', NULL, 'What is the doctrine of reasonable expectations?', '¿Qué es la doctrina de expectativas razonables?', '["Insurers expect premiums", "Courts may interpret policy language in favor of what a reasonable insured would expect", "Agents expect commissions", "Insurers control all interpretations"]', '["Los aseguradores esperan primas", "Los tribunales pueden interpretar el lenguaje de la póliza a favor de lo que un asegurado razonable esperaría", "Los agentes esperan comisiones", "Los aseguradores controlan todas las interpretaciones"]', 1, 'The doctrine of reasonable expectations holds that ambiguous policy language should be interpreted according to what a reasonable insured would expect.', 'La doctrina de expectativas razonables sostiene que el lenguaje ambiguo de la póliza debe interpretarse según lo que un asegurado razonable esperaría.', true, '2026-01-14 23:13:37.351108', '2026-01-14 23:13:37.351108') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a7343255-d080-40da-9a9e-aa57bdc5c4b1', 'general_lines', NULL, 'What is bailee coverage?', '¿Qué es la cobertura de depositario?', '["Coverage for bail bonds", "Coverage for property of others in the care of the insured", "Life insurance", "Auto coverage"]', '["Cobertura para fianzas de libertad bajo fianza", "Cobertura para propiedad de otros bajo el cuidado del asegurado", "Seguro de vida", "Cobertura de auto"]', 1, 'Bailee coverage protects businesses for damage to customer property left in their care, custody, or control.', 'La cobertura de depositario protege a los negocios por daños a la propiedad de clientes dejada bajo su cuidado, custodia o control.', true, '2026-01-14 23:10:18.234523', '2026-01-14 23:10:18.234523') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('a90c14c8-4d78-4f47-a38c-7c6efe79d19c', 'general_lines', NULL, 'What is an admitted insurance company?', '¿Qué es una compañía de seguros admitida?', '["Any insurance company", "A company licensed to write insurance in a particular state", "A company that admits claims", "A surplus lines insurer"]', '["Cualquier compañía de seguros", "Una compañía autorizada para escribir seguros en un estado particular", "Una compañía que admite reclamos", "Un asegurador de líneas excedentes"]', 1, 'An admitted insurer is licensed by the state to sell insurance and is subject to state regulations and guaranty fund protection.', 'Un asegurador admitido está autorizado por el estado para vender seguros y está sujeto a regulaciones estatales y protección del fondo de garantía.', true, '2026-01-14 23:13:37.299223', '2026-01-14 23:13:37.299223') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('aa20a45f-ae66-4e24-8f13-47bdbe8a29d2', 'general_lines', NULL, 'What is an endorsement in insurance?', '¿Qué es un endoso en seguros?', '["A signature on a check", "A written document that modifies the original policy", "A type of surety bond", "A claim form"]', '["Una firma en un cheque", "Un documento escrito que modifica la póliza original", "Un tipo de fianza", "Un formulario de reclamo"]', 1, 'An endorsement (or rider) is a written document attached to a policy that modifies, adds, or removes coverage.', 'Un endoso (o anexo) es un documento escrito adjunto a una póliza que modifica, agrega o elimina cobertura.', true, '2026-01-14 23:10:18.11019', '2026-01-14 23:10:18.11019') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('aa39bee7-c058-4de4-bb16-a70a8170ab78', 'general_lines', NULL, 'What is risk avoidance?', '¿Qué es la evitación de riesgos?', '["Purchasing insurance", "Eliminating exposure to a risk by not engaging in the activity", "Transferring risk", "Reducing risk"]', '["Comprar seguro", "Eliminar la exposición a un riesgo al no participar en la actividad", "Transferir el riesgo", "Reducir el riesgo"]', 1, 'Risk avoidance eliminates exposure to a potential loss by choosing not to engage in the activity that creates the risk.', 'La evitación de riesgos elimina la exposición a una pérdida potencial al elegir no participar en la actividad que crea el riesgo.', true, '2026-01-14 23:23:20.959082', '2026-01-14 23:23:20.959082') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ab6d08e1-6106-4b1a-acc1-345c69bad4b4', 'general_lines', NULL, 'What is medical payments coverage in commercial auto?', '¿Qué es la cobertura de pagos médicos en auto comercial?', '["Health insurance", "Coverage for medical expenses of occupants of the insured vehicle regardless of fault", "Liability coverage", "Property coverage"]', '["Seguro de salud", "Cobertura para gastos médicos de ocupantes del vehículo asegurado sin importar la culpa", "Cobertura de responsabilidad", "Cobertura de propiedad"]', 1, 'Medical payments coverage pays medical expenses for injuries to the driver and passengers of the insured vehicle, regardless of who is at fault.', 'La cobertura de pagos médicos paga gastos médicos por lesiones al conductor y pasajeros del vehículo asegurado, sin importar quién tiene la culpa.', true, '2026-01-14 23:16:55.569928', '2026-01-14 23:16:55.569928') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ac447b8a-a4ce-446a-af7b-9050e48609c7', 'general_lines', NULL, 'What is salvage in insurance?', '¿Qué es el salvamento en seguros?', '["A type of coverage", "Property recovered by the insurer after paying a total loss", "A premium discount", "An exclusion"]', '["Un tipo de cobertura", "Propiedad recuperada por el asegurador después de pagar una pérdida total", "Un descuento de prima", "Una exclusión"]', 1, 'Salvage is the damaged property that belongs to the insurer after paying a total loss claim, which the insurer can sell to reduce the net loss.', 'El salvamento es la propiedad dañada que pertenece al asegurador después de pagar un reclamo de pérdida total, que el asegurador puede vender para reducir la pérdida neta.', true, '2026-01-14 23:23:21.0061', '2026-01-14 23:23:21.0061') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ad31af8d-42b8-4aee-92e7-b5d5c23fa3dc', 'general_lines', NULL, 'What is surplus lines insurance?', '¿Qué es el seguro de líneas excedentes?', '["Extra coverage", "Insurance from non-admitted carriers for risks that admitted insurers won''t cover", "Excess liability insurance", "Life insurance"]', '["Cobertura extra", "Seguro de aseguradores no admitidos para riesgos que los aseguradores admitidos no cubrirán", "Seguro de responsabilidad excedente", "Seguro de vida"]', 1, 'Surplus lines insurance is coverage placed with non-admitted insurers for risks that cannot be placed with admitted carriers in the standard market.', 'El seguro de líneas excedentes es cobertura colocada con aseguradores no admitidos para riesgos que no pueden colocarse con aseguradores admitidos en el mercado estándar.', true, '2026-01-14 23:13:37.301493', '2026-01-14 23:13:37.301493') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ad6718fb-4ea4-4132-80b6-7a6a84cb32b8', 'general_lines', NULL, 'What is the purpose of a commercial auto policy?', '¿Cuál es el propósito de una póliza de auto comercial?', '["To cover personal vehicles only", "To provide coverage for vehicles used in business operations", "To cover only liability", "To provide life insurance"]', '["Cubrir solo vehículos personales", "Proporcionar cobertura para vehículos utilizados en operaciones comerciales", "Cubrir solo responsabilidad", "Proporcionar seguro de vida"]', 1, 'A commercial auto policy provides liability, physical damage, and other coverage for vehicles owned, leased, hired, or borrowed for business purposes.', 'Una póliza de auto comercial proporciona responsabilidad, daños físicos y otra cobertura para vehículos propiedad, arrendados, alquilados o prestados para propósitos comerciales.', true, '2026-01-14 23:10:18.182338', '2026-01-14 23:10:18.182338') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ad9412ac-90c1-42bf-82e7-2e865850da4b', 'general_lines', NULL, 'What are policy conditions?', '¿Qué son las condiciones de la póliza?', '["Types of coverage", "Provisions that describe the rights and duties of both the insurer and the insured", "Exclusions", "Endorsements"]', '["Tipos de cobertura", "Disposiciones que describen los derechos y deberes tanto del asegurador como del asegurado", "Exclusiones", "Endosos"]', 1, 'Policy conditions are provisions that describe the responsibilities and requirements of both the insurer and insured, such as notice requirements and cooperation duties.', 'Las condiciones de la póliza son disposiciones que describen las responsabilidades y requisitos tanto del asegurador como del asegurado, como requisitos de aviso y deberes de cooperación.', true, '2026-01-14 23:13:37.318313', '2026-01-14 23:13:37.318313') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b012e759-9c12-440c-b44f-c233540cb443', 'general_lines', NULL, 'What is risk transfer?', '¿Qué es la transferencia de riesgos?', '["Keeping all risks", "Shifting the financial consequences of risk to another party, such as through insurance", "Avoiding risks", "Reducing risks"]', '["Mantener todos los riesgos", "Trasladar las consecuencias financieras del riesgo a otra parte, como a través del seguro", "Evitar riesgos", "Reducir riesgos"]', 1, 'Risk transfer shifts the financial consequences of potential losses to another party, typically through insurance contracts or hold harmless agreements.', 'La transferencia de riesgos traslada las consecuencias financieras de las pérdidas potenciales a otra parte, típicamente a través de contratos de seguro o acuerdos de exoneración.', true, '2026-01-14 23:23:20.962656', '2026-01-14 23:23:20.962656') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b182092c-e9cd-405f-bfb9-4fb051296f79', 'general_lines', NULL, 'What is a fiduciary bond?', '¿Qué es una fianza fiduciaria?', '["A performance bond", "A bond guaranteeing faithful performance by persons in positions of trust", "A bid bond", "A payment bond"]', '["Una fianza de cumplimiento", "Una fianza que garantiza el desempeño fiel de personas en posiciones de confianza", "Una fianza de licitación", "Una fianza de pago"]', 1, 'A fiduciary bond guarantees faithful performance by a person in a position of trust, such as an executor, administrator, or trustee.', 'Una fianza fiduciaria garantiza el desempeño fiel de una persona en una posición de confianza, como un ejecutor, administrador o fideicomisario.', true, '2026-01-14 23:16:55.499399', '2026-01-14 23:16:55.499399') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b2dcc011-4f80-466d-939e-bf4287178f59', 'general_lines', NULL, 'What is dealers open lot coverage?', '¿Qué es la cobertura de lote abierto de concesionarios?', '["Liability coverage", "Coverage for damage to vehicles in an auto dealer''s inventory", "Life insurance", "Health insurance"]', '["Cobertura de responsabilidad", "Cobertura por daños a vehículos en el inventario de un concesionario de autos", "Seguro de vida", "Seguro de salud"]', 1, 'Dealers open lot coverage protects auto dealers for physical damage to vehicles in their inventory while on the dealer''s lot.', 'La cobertura de lote abierto de concesionarios protege a los concesionarios de autos por daños físicos a vehículos en su inventario mientras están en el lote del concesionario.', true, '2026-01-14 23:16:55.561343', '2026-01-14 23:16:55.561343') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b41056b1-1f68-4e6f-a754-c16dd2b556ad', 'general_lines', NULL, 'What is terrorism insurance coverage?', '¿Qué es la cobertura de seguro contra terrorismo?', '["Always included free", "Coverage for losses from certified acts of terrorism, often through TRIA", "Life insurance only", "Auto coverage"]', '["Siempre incluida gratis", "Cobertura para pérdidas por actos certificados de terrorismo, a menudo a través de TRIA", "Solo seguro de vida", "Cobertura de auto"]', 1, 'Terrorism coverage protects against certified acts of terrorism and is backed by the federal government through the Terrorism Risk Insurance Act (TRIA).', 'La cobertura contra terrorismo protege contra actos certificados de terrorismo y está respaldada por el gobierno federal a través de la Ley de Seguro de Riesgo de Terrorismo (TRIA).', true, '2026-01-14 23:23:21.018178', '2026-01-14 23:23:21.018178') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('b842c3c6-43a2-4562-b387-8d8439a5e5ac', 'general_lines', NULL, 'What is nonrenewal in insurance?', '¿Qué es la no renovación en seguros?', '["Policy cancellation", "The insurer''s decision not to renew a policy at the end of its term", "A premium discount", "An endorsement"]', '["Cancelación de póliza", "La decisión del asegurador de no renovar una póliza al final de su término", "Un descuento de prima", "Un endoso"]', 1, 'Nonrenewal is the insurer''s decision not to renew a policy when it expires, which requires proper advance notice to the policyholder.', 'La no renovación es la decisión del asegurador de no renovar una póliza cuando expira, lo cual requiere aviso previo apropiado al titular de la póliza.', true, '2026-01-14 23:23:21.027095', '2026-01-14 23:23:21.027095') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('bcf79476-c59c-4140-8164-3f75e3b2f686', 'general_lines', NULL, 'What is short rate cancellation?', '¿Qué es la cancelación a tasa corta?', '["A full refund", "A cancellation method where a penalty is applied to the return premium", "A pro rata refund", "A premium increase"]', '["Un reembolso completo", "Un método de cancelación donde se aplica una penalidad al reembolso de prima", "Un reembolso prorrateado", "Un aumento de prima"]', 1, 'Short rate cancellation applies a penalty to the premium refund when the insured requests cancellation, retaining more premium than a pro rata return.', 'La cancelación a tasa corta aplica una penalidad al reembolso de prima cuando el asegurado solicita la cancelación, reteniendo más prima que un retorno prorrateado.', true, '2026-01-14 23:23:21.02975', '2026-01-14 23:23:21.02975') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('bfcb7d5d-3928-4360-b7a1-82855e0ba45c', 'general_lines', NULL, 'What is supplementary payments coverage in CGL?', '¿Qué es la cobertura de pagos suplementarios en CGL?', '["Additional premium payments", "Coverage for expenses like bail bonds and loss of earnings in addition to defense costs", "Extra claim payments", "Premium refunds"]', '["Pagos de prima adicionales", "Cobertura para gastos como fianzas y pérdida de ganancias además de costos de defensa", "Pagos de reclamos extra", "Reembolsos de prima"]', 1, 'Supplementary payments cover certain costs in addition to defense, such as bail bonds, loss of earnings for attending trials, and post-judgment interest.', 'Los pagos suplementarios cubren ciertos costos además de defensa, como fianzas, pérdida de ganancias por asistir a juicios e intereses post-sentencia.', true, '2026-01-14 23:16:55.548097', '2026-01-14 23:16:55.548097') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c0e03ff6-9748-4316-b4a7-ac49e92f76c1', 'general_lines', NULL, 'What is vicarious liability?', '¿Qué es la responsabilidad vicaria?', '["Personal liability only", "Liability for the actions of another person, such as an employee", "Product liability", "Property liability"]', '["Solo responsabilidad personal", "Responsabilidad por las acciones de otra persona, como un empleado", "Responsabilidad por productos", "Responsabilidad de propiedad"]', 1, 'Vicarious liability holds one party responsible for the actions of another, such as an employer being liable for employee actions within the scope of employment.', 'La responsabilidad vicaria hace responsable a una parte por las acciones de otra, como un empleador siendo responsable de las acciones de un empleado dentro del alcance del empleo.', true, '2026-01-14 23:13:37.256698', '2026-01-14 23:13:37.256698') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c2e4b970-5431-46fd-b58c-4e71dc332b84', 'general_lines', NULL, 'What is a schedule in an insurance policy?', '¿Qué es un anexo en una póliza de seguro?', '["A payment plan", "A list of covered items, locations, or values specific to the policy", "A cancellation date", "A type of coverage"]', '["Un plan de pago", "Una lista de artículos cubiertos, ubicaciones o valores específicos de la póliza", "Una fecha de cancelación", "Un tipo de cobertura"]', 1, 'A schedule is a document attached to a policy listing specific items, locations, values, or other details particular to that policy.', 'Un anexo es un documento adjunto a una póliza que lista artículos específicos, ubicaciones, valores u otros detalles particulares de esa póliza.', true, '2026-01-14 23:13:37.260236', '2026-01-14 23:13:37.260236') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c30bde0f-40dd-4a2a-8b0a-85ef7089cb98', 'general_lines', NULL, 'What is the penalty for selling insurance without a license in Texas?', '¿Cuál es la penalidad por vender seguros sin licencia en Texas?', '["No penalty", "Criminal penalties including fines and possible imprisonment", "Only a warning", "Only premium refund"]', '["Sin penalidad", "Penalidades criminales incluyendo multas y posible encarcelamiento", "Solo una advertencia", "Solo reembolso de prima"]', 1, 'Selling insurance without a license in Texas is a criminal offense that can result in fines, imprisonment, and other penalties under the Texas Insurance Code.', 'Vender seguros sin licencia en Texas es un delito criminal que puede resultar en multas, encarcelamiento y otras penalidades bajo el Código de Seguros de Texas.', true, '2026-01-14 23:23:21.042022', '2026-01-14 23:23:21.042022') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c6d9f444-8633-4c94-9bc2-ef9eda1002df', 'general_lines', NULL, 'What is the duty of utmost good faith in insurance?', '¿Qué es el deber de máxima buena fe en seguros?', '["The obligation of both parties to disclose all material information honestly", "A type of coverage", "A premium requirement", "A claims process"]', '["La obligación de ambas partes de divulgar toda la información material honestamente", "Un tipo de cobertura", "Un requisito de prima", "Un proceso de reclamos"]', 0, 'Utmost good faith requires both the insurer and insured to deal honestly and disclose all material facts in an insurance contract.', 'La máxima buena fe requiere que tanto el asegurador como el asegurado traten honestamente y divulguen todos los hechos materiales en un contrato de seguro.', true, '2026-01-14 18:28:35.69976', '2026-01-14 18:28:35.69976') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c6ddd6f2-368e-4385-b1fa-b2c48c16400a', 'general_lines', NULL, 'What is a builders risk policy?', '¿Qué es una póliza de riesgo de constructores?', '["Insurance for property owners only", "Coverage for buildings under construction", "Life insurance for builders", "Auto insurance for contractors"]', '["Seguro solo para propietarios de propiedad", "Cobertura para edificios en construcción", "Seguro de vida para constructores", "Seguro de auto para contratistas"]', 1, 'A builders risk policy provides coverage for buildings under construction against damage from covered perils such as fire, theft, and weather.', 'Una póliza de riesgo de constructores proporciona cobertura para edificios en construcción contra daños de riesgos cubiertos como incendio, robo y clima.', true, '2026-01-14 23:10:18.202904', '2026-01-14 23:10:18.202904') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('c8bfd88e-3dbf-41f3-9abc-0d64f154e0f4', 'general_lines', NULL, 'What is a material misrepresentation?', '¿Qué es una tergiversación material?', '["A minor error", "A false statement that would affect the insurer''s decision to issue or price the policy", "A premium calculation", "An endorsement"]', '["Un error menor", "Una declaración falsa que afectaría la decisión del asegurador de emitir o fijar el precio de la póliza", "Un cálculo de prima", "Un endoso"]', 1, 'A material misrepresentation is a false or misleading statement that would have influenced the insurer''s decision to accept the risk or the terms of coverage.', 'Una tergiversación material es una declaración falsa o engañosa que habría influido en la decisión del asegurador de aceptar el riesgo o los términos de la cobertura.', true, '2026-01-14 23:13:37.336968', '2026-01-14 23:13:37.336968') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ca4f73b1-deef-42b2-81d9-bd37a0973b36', 'general_lines', NULL, 'What is the purpose of a deductible in insurance?', '¿Cuál es el propósito de un deducible en seguros?', '["To increase claim payments", "To have the insured share in the loss and reduce small claims", "To eliminate all coverage", "To replace the premium"]', '["Aumentar los pagos de reclamos", "Hacer que el asegurado comparta la pérdida y reducir reclamos pequeños", "Eliminar toda la cobertura", "Reemplazar la prima"]', 1, 'A deductible is the amount the insured must pay out of pocket before insurance coverage applies, reducing moral hazard and small claims.', 'Un deducible es la cantidad que el asegurado debe pagar de su bolsillo antes de que se aplique la cobertura del seguro, reduciendo el riesgo moral y los reclamos pequeños.', true, '2026-01-14 23:10:18.170551', '2026-01-14 23:10:18.170551') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('cb37a348-0bc8-43d7-b0ad-d2b02c1a8851', 'general_lines', NULL, 'What is a claim adjuster?', '¿Qué es un ajustador de reclamos?', '["An insurance salesperson", "A person who investigates claims and determines payment amounts", "A policy underwriter", "A premium collector"]', '["Un vendedor de seguros", "Una persona que investiga reclamos y determina los montos de pago", "Un suscriptor de pólizas", "Un cobrador de primas"]', 1, 'A claim adjuster investigates insurance claims, evaluates damages, determines coverage, and negotiates settlements with claimants.', 'Un ajustador de reclamos investiga reclamos de seguros, evalúa daños, determina la cobertura y negocia acuerdos con los reclamantes.', true, '2026-01-14 23:23:20.980283', '2026-01-14 23:23:20.980283') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('cc86d6e3-84d9-4455-947b-c709c8c04679', 'general_lines', NULL, 'What is a self-insured retention (SIR)?', '¿Qué es una retención autoasegurada (SIR)?', '["A type of coverage", "The amount the insured must pay before excess or umbrella coverage applies", "A premium payment", "An endorsement"]', '["Un tipo de cobertura", "La cantidad que el asegurado debe pagar antes de que se aplique la cobertura excedente o paraguas", "Un pago de prima", "Un endoso"]', 1, 'A self-insured retention is a dollar amount the insured is responsible for before excess or umbrella coverage begins to pay.', 'Una retención autoasegurada es una cantidad en dólares de la cual el asegurado es responsable antes de que la cobertura excedente o paraguas comience a pagar.', true, '2026-01-14 23:13:37.357331', '2026-01-14 23:13:37.357331') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('cea9fff6-addd-4c33-92db-0e8c7731241c', 'general_lines', NULL, 'What is directors and officers (D&O) liability insurance?', '¿Qué es el seguro de responsabilidad de directores y funcionarios (D&O)?', '["Property insurance", "Coverage for claims against corporate leadership for wrongful acts", "Auto insurance", "Workers compensation"]', '["Seguro de propiedad", "Cobertura para reclamos contra liderazgo corporativo por actos ilícitos", "Seguro de auto", "Compensación de trabajadores"]', 1, 'D&O insurance protects company directors and officers from personal liability for wrongful acts in managing the company.', 'El seguro D&O protege a los directores y funcionarios de la empresa de responsabilidad personal por actos ilícitos en la gestión de la empresa.', true, '2026-01-14 23:10:18.221119', '2026-01-14 23:10:18.221119') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d0a1fb2a-5697-4229-9a8a-fa520c064579', 'general_lines', NULL, 'What is the minimum age to be licensed as an insurance agent in Texas?', '¿Cuál es la edad mínima para obtener licencia como agente de seguros en Texas?', '["18 years old", "21 years old", "25 years old", "16 years old"]', '["18 años", "21 años", "25 años", "16 años"]', 0, 'In Texas, you must be at least 18 years old to be licensed as an insurance agent.', 'En Texas, debes tener al menos 18 años para obtener licencia como agente de seguros.', true, '2026-01-14 18:28:35.675827', '2026-01-14 18:28:35.675827') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d12a6488-e811-4667-bb8f-08a29c731791', 'general_lines', NULL, 'What is concurrent causation?', '¿Qué es la causación concurrente?', '["A type of policy", "When two or more causes contribute to a loss, one covered and one excluded", "A claims process", "A premium calculation"]', '["Un tipo de póliza", "Cuando dos o más causas contribuyen a una pérdida, una cubierta y una excluida", "Un proceso de reclamos", "Un cálculo de prima"]', 1, 'Concurrent causation occurs when two or more causes (one covered, one excluded) contribute to a loss, potentially triggering coverage disputes.', 'La causación concurrente ocurre cuando dos o más causas (una cubierta, una excluida) contribuyen a una pérdida, potencialmente generando disputas de cobertura.', true, '2026-01-14 23:13:37.321603', '2026-01-14 23:13:37.321603') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d25ed58d-5b76-49a2-b7ec-633ca9362eef', 'general_lines', NULL, 'What is the mobile equipment exclusion in commercial auto policies?', '¿Qué es la exclusión de equipo móvil en pólizas de auto comercial?', '["An exclusion for trucks", "An exclusion for vehicles primarily designed for off-road use that may be covered under CGL instead", "An exclusion for trailers", "An exclusion for motorcycles"]', '["Una exclusión para camiones", "Una exclusión para vehículos diseñados principalmente para uso fuera de carretera que pueden estar cubiertos bajo CGL en su lugar", "Una exclusión para remolques", "Una exclusión para motocicletas"]', 1, 'Mobile equipment (bulldozers, forklifts, etc.) is excluded from commercial auto policies because liability for such equipment is typically covered under CGL.', 'El equipo móvil (bulldozers, montacargas, etc.) está excluido de las pólizas de auto comercial porque la responsabilidad por dicho equipo típicamente está cubierta bajo CGL.', true, '2026-01-14 23:16:55.550757', '2026-01-14 23:16:55.550757') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d46ede2e-6a63-41af-a7a3-afce72bcdc1d', 'general_lines', NULL, 'What is a general aggregate limit?', '¿Qué es un límite agregado general?', '["A per claim limit", "The maximum the insurer will pay for all covered claims (except products/completed operations) in a policy period", "A deductible", "The premium"]', '["Un límite por reclamo", "El máximo que el asegurador pagará por todos los reclamos cubiertos (excepto productos/operaciones completadas) en un período de póliza", "Un deducible", "La prima"]', 1, 'The general aggregate is the maximum the insurer will pay for all claims other than products-completed operations during a policy period.', 'El agregado general es el máximo que el asegurador pagará por todos los reclamos excepto productos-operaciones completadas durante un período de póliza.', true, '2026-01-14 23:16:55.535623', '2026-01-14 23:16:55.535623') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d5425735-8258-4c96-a9c4-fedf074ad4be', 'general_lines', NULL, 'What is facultative reinsurance?', '¿Qué es el reaseguro facultativo?', '["Automatic reinsurance", "Reinsurance negotiated on a case-by-case basis for individual risks", "Group reinsurance", "Life reinsurance"]', '["Reaseguro automático", "Reaseguro negociado caso por caso para riesgos individuales", "Reaseguro grupal", "Reaseguro de vida"]', 1, 'Facultative reinsurance is arranged on a case-by-case basis where the reinsurer evaluates and chooses whether to accept each individual risk.', 'El reaseguro facultativo se arregla caso por caso donde el reasegurador evalúa y elige si acepta cada riesgo individual.', true, '2026-01-14 23:13:37.366544', '2026-01-14 23:13:37.366544') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d66d646a-e9cf-4985-9042-d1a709caf736', 'general_lines', NULL, 'What is the notice of loss requirement?', '¿Qué es el requisito de aviso de pérdida?', '["A premium notice", "The insured''s duty to promptly inform the insurer of a loss or potential claim", "A renewal notice", "A cancellation notice"]', '["Un aviso de prima", "El deber del asegurado de informar prontamente al asegurador de una pérdida o reclamo potencial", "Un aviso de renovación", "Un aviso de cancelación"]', 1, 'The notice of loss requirement obligates the insured to notify the insurer promptly after a loss occurs or when a claim is likely to be made.', 'El requisito de aviso de pérdida obliga al asegurado a notificar al asegurador prontamente después de que ocurre una pérdida o cuando es probable que se haga un reclamo.', true, '2026-01-14 23:23:20.999663', '2026-01-14 23:23:20.999663') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('d8f045b1-ab3c-4e1f-a9cb-116ec4a99442', 'general_lines', NULL, 'What is the purpose of a surety bond?', '¿Cuál es el propósito de una fianza?', '["To provide life insurance", "To guarantee performance or payment of an obligation", "To cover auto accidents", "To pay medical bills"]', '["Proporcionar seguro de vida", "Garantizar el cumplimiento o pago de una obligación", "Cubrir accidentes de auto", "Pagar facturas médicas"]', 1, 'A surety bond is a three-party agreement that guarantees the principal will fulfill an obligation to the obligee.', 'Una fianza es un acuerdo de tres partes que garantiza que el principal cumplirá una obligación con el obligado.', true, '2026-01-14 23:10:18.087878', '2026-01-14 23:10:18.087878') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('daff42a4-9fb4-4dd1-b4de-73933f62cda4', 'general_lines', NULL, 'What is the difference between concealment and misrepresentation?', '¿Cuál es la diferencia entre ocultación y tergiversación?', '["No difference", "Concealment is failure to disclose; misrepresentation is making a false statement", "Both are the same thing", "Concealment is always fraud"]', '["Sin diferencia", "Ocultación es no revelar; tergiversación es hacer una declaración falsa", "Ambos son lo mismo", "Ocultación siempre es fraude"]', 1, 'Concealment is the intentional failure to disclose material information, while misrepresentation is making a false or misleading statement.', 'La ocultación es la falta intencional de revelar información material, mientras que la tergiversación es hacer una declaración falsa o engañosa.', true, '2026-01-14 23:13:37.339649', '2026-01-14 23:13:37.339649') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('db37d948-65e9-47c6-80a9-1f220a104e7b', 'general_lines', NULL, 'What is the purpose of umbrella liability insurance?', '¿Cuál es el propósito del seguro de responsabilidad paraguas?', '["To replace other policies", "To provide excess liability coverage above underlying policy limits", "To cover property only", "To provide workers compensation"]', '["Reemplazar otras pólizas", "Proporcionar cobertura de responsabilidad excedente por encima de los límites de la póliza subyacente", "Cubrir solo propiedad", "Proporcionar compensación de trabajadores"]', 1, 'Umbrella liability insurance provides additional liability coverage above the limits of underlying policies and may cover some claims excluded by underlying policies.', 'El seguro de responsabilidad paraguas proporciona cobertura de responsabilidad adicional por encima de los límites de las pólizas subyacentes y puede cubrir algunos reclamos excluidos por las pólizas subyacentes.', true, '2026-01-14 23:10:18.132905', '2026-01-14 23:10:18.132905') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('db84bdfe-23d7-43eb-af25-8f2e9f1c6725', 'general_lines', NULL, 'What is the Texas agent licensing examination requirement?', '¿Cuál es el requisito del examen de licencia de agente de Texas?', '["No exam required", "Passing a state-administered examination covering insurance principles and laws", "Only a background check", "Only a fee payment"]', '["No se requiere examen", "Aprobar un examen administrado por el estado que cubre principios y leyes de seguros", "Solo una verificación de antecedentes", "Solo un pago de tarifa"]', 1, 'Texas requires prospective agents to pass a licensing examination testing knowledge of insurance principles, coverage, and Texas insurance laws.', 'Texas requiere que los agentes potenciales aprueben un examen de licencia que evalúa el conocimiento de principios de seguros, cobertura y leyes de seguros de Texas.', true, '2026-01-14 23:23:21.036063', '2026-01-14 23:23:21.036063') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('dbbc5c3c-c09d-44d6-bd60-70afba755aea', 'general_lines', NULL, 'What is business interruption insurance?', '¿Qué es el seguro de interrupción de negocios?', '["Coverage for employee injuries", "Coverage for lost income when a business cannot operate due to a covered loss", "Coverage for auto accidents", "Coverage for professional errors"]', '["Cobertura para lesiones de empleados", "Cobertura para ingresos perdidos cuando un negocio no puede operar debido a una pérdida cubierta", "Cobertura para accidentes de auto", "Cobertura para errores profesionales"]', 1, 'Business interruption insurance covers lost income and ongoing expenses when a business is unable to operate due to a covered property loss.', 'El seguro de interrupción de negocios cubre ingresos perdidos y gastos continuos cuando un negocio no puede operar debido a una pérdida de propiedad cubierta.', true, '2026-01-14 23:10:18.154625', '2026-01-14 23:10:18.154625') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('dc112b1d-93d0-4f6b-998f-9694078b1b2f', 'general_lines', NULL, 'What is contractual liability?', '¿Qué es la responsabilidad contractual?', '["Only statutory liability", "Liability assumed through a contract or agreement", "Product liability", "Auto liability"]', '["Solo responsabilidad estatutaria", "Responsabilidad asumida a través de un contrato o acuerdo", "Responsabilidad por productos", "Responsabilidad de auto"]', 1, 'Contractual liability is liability that the insured assumes under a contract, such as a hold harmless or indemnity agreement.', 'La responsabilidad contractual es la responsabilidad que el asegurado asume bajo un contrato, como un acuerdo de exoneración o indemnización.', true, '2026-01-14 23:13:37.385833', '2026-01-14 23:13:37.385833') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('dc315c29-d5d7-41c3-8f79-3006eb3c26f3', 'general_lines', NULL, 'What is twisting in insurance?', '¿Qué es el ''twisting'' en seguros?', '["A legal sales practice", "Using misrepresentation to induce a policyholder to replace an existing policy", "A type of endorsement", "A coverage modification"]', '["Una práctica de ventas legal", "Usar tergiversación para inducir a un titular de póliza a reemplazar una póliza existente", "Un tipo de endoso", "Una modificación de cobertura"]', 1, 'Twisting is an illegal practice involving misrepresentation to induce a policyholder to lapse, forfeit, or surrender an existing policy to purchase a new one.', 'El twisting es una práctica ilegal que involucra tergiversación para inducir a un titular de póliza a dejar vencer, perder o rendir una póliza existente para comprar una nueva.', true, '2026-01-14 23:13:37.280007', '2026-01-14 23:13:37.280007') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('dcf451de-3093-4ab6-9a7f-6db947790881', 'general_lines', NULL, 'What is the purpose of a Business Owner''s Policy (BOP)?', '¿Cuál es el propósito de una Póliza de Propietario de Negocio (BOP)?', '["To cover only liability", "To combine property and liability coverage in one package for small businesses", "To cover only employees", "To provide life insurance"]', '["Cubrir solo responsabilidad", "Combinar cobertura de propiedad y responsabilidad en un paquete para pequeños negocios", "Cubrir solo empleados", "Proporcionar seguro de vida"]', 1, 'A BOP combines property insurance, business interruption insurance, and liability coverage into a single package for eligible small to mid-sized businesses.', 'Una BOP combina seguro de propiedad, seguro de interrupción de negocios y cobertura de responsabilidad en un solo paquete para pequeños y medianos negocios elegibles.', true, '2026-01-14 23:10:18.113426', '2026-01-14 23:10:18.113426') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('de8ffd05-d309-4f67-a798-201c92578fcd', 'general_lines', NULL, 'What is spoilage coverage?', '¿Qué es la cobertura de deterioro?', '["Coverage for employee theft", "Coverage for loss of perishable goods due to temperature change or power failure", "Auto coverage", "Life insurance"]', '["Cobertura para robo de empleados", "Cobertura por pérdida de bienes perecederos debido a cambio de temperatura o falla de energía", "Cobertura de auto", "Seguro de vida"]', 1, 'Spoilage coverage protects against loss of perishable stock due to breakdown of refrigeration equipment, power failure, or temperature change.', 'La cobertura de deterioro protege contra pérdida de stock perecedero debido a avería de equipo de refrigeración, falla de energía o cambio de temperatura.', true, '2026-01-14 23:16:55.445877', '2026-01-14 23:16:55.445877') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e3517be7-654f-41b7-b3e3-ad2ed3d884c7', 'general_lines', NULL, 'What is the proof of loss requirement?', '¿Qué es el requisito de prueba de pérdida?', '["A premium payment", "A sworn statement documenting the facts and amount of the loss", "An insurance application", "A policy renewal"]', '["Un pago de prima", "Una declaración jurada documentando los hechos y el monto de la pérdida", "Una solicitud de seguro", "Una renovación de póliza"]', 1, 'Proof of loss is a formal sworn statement the insured must submit to the insurance company documenting the details and amount of a claimed loss.', 'La prueba de pérdida es una declaración jurada formal que el asegurado debe presentar a la compañía de seguros documentando los detalles y el monto de una pérdida reclamada.', true, '2026-01-14 23:23:20.989163', '2026-01-14 23:23:20.989163') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e4112d15-94c6-44f7-96ce-5939f1afa4bf', 'general_lines', NULL, 'What is a commercial crime policy?', '¿Qué es una póliza de crimen comercial?', '["Coverage for criminal defendants", "Coverage for losses caused by criminal acts against the business", "Auto coverage", "Life insurance"]', '["Cobertura para acusados criminales", "Cobertura por pérdidas causadas por actos criminales contra el negocio", "Cobertura de auto", "Seguro de vida"]', 1, 'A commercial crime policy covers losses from criminal acts including employee theft, forgery, computer fraud, and funds transfer fraud.', 'Una póliza de crimen comercial cubre pérdidas por actos criminales incluyendo robo de empleados, falsificación, fraude informático y fraude de transferencia de fondos.', true, '2026-01-14 23:16:55.374759', '2026-01-14 23:16:55.374759') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e6b9b601-88f9-4458-b755-7b79c5f21567', 'general_lines', NULL, 'What is the purpose of reinsurance?', '¿Cuál es el propósito del reaseguro?', '["To sell more insurance", "To allow insurers to transfer portions of their risk to other insurers", "To eliminate all risk", "To reduce premiums"]', '["Vender más seguros", "Permitir que los aseguradores transfieran porciones de su riesgo a otros aseguradores", "Eliminar todo el riesgo", "Reducir las primas"]', 1, 'Reinsurance allows primary insurers to transfer part of their risk exposure to other insurers, helping manage capacity and catastrophic losses.', 'El reaseguro permite a los aseguradores primarios transferir parte de su exposición al riesgo a otros aseguradores, ayudando a gestionar la capacidad y las pérdidas catastróficas.', true, '2026-01-14 23:13:37.363506', '2026-01-14 23:13:37.363506') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('e8a2f157-9fdb-4684-835b-9c585eaa54da', 'general_lines', NULL, 'What is hull insurance?', '¿Qué es el seguro de casco?', '["Life insurance for sailors", "Coverage for the physical structure of a vessel", "Cargo coverage", "Liability coverage"]', '["Seguro de vida para marineros", "Cobertura para la estructura física de una embarcación", "Cobertura de carga", "Cobertura de responsabilidad"]', 1, 'Hull insurance covers physical damage to the vessel (ship''s body and machinery) from covered perils.', 'El seguro de casco cubre daños físicos a la embarcación (cuerpo del barco y maquinaria) de riesgos cubiertos.', true, '2026-01-14 23:16:55.482525', '2026-01-14 23:16:55.482525') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ea0bbb81-c944-4b34-895d-c616cec6115f', 'general_lines', NULL, 'What is a public adjuster?', '¿Qué es un ajustador público?', '["An insurance company employee", "An adjuster who represents policyholders in claim negotiations", "A government official", "A court-appointed adjuster"]', '["Un empleado de la compañía de seguros", "Un ajustador que representa a los titulares de pólizas en negociaciones de reclamos", "Un funcionario del gobierno", "Un ajustador nombrado por el tribunal"]', 1, 'A public adjuster is hired by policyholders to represent their interests in claim negotiations with the insurance company, usually for a percentage of the settlement.', 'Un ajustador público es contratado por los titulares de pólizas para representar sus intereses en negociaciones de reclamos con la compañía de seguros, generalmente por un porcentaje del acuerdo.', true, '2026-01-14 23:23:20.984018', '2026-01-14 23:23:20.984018') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('eab1b11d-3626-4c68-ad1e-8ee9d5c9bacc', 'general_lines', NULL, 'What is frequency in risk analysis?', '¿Qué es la frecuencia en el análisis de riesgos?', '["The size of losses", "How often losses are expected to occur", "The cost of insurance", "The premium amount"]', '["El tamaño de las pérdidas", "Con qué frecuencia se espera que ocurran las pérdidas", "El costo del seguro", "El monto de la prima"]', 1, 'Frequency refers to how often losses are expected to occur, which helps determine appropriate risk management techniques.', 'La frecuencia se refiere a con qué frecuencia se espera que ocurran las pérdidas, lo que ayuda a determinar técnicas apropiadas de gestión de riesgos.', true, '2026-01-14 23:23:20.97282', '2026-01-14 23:23:20.97282') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('eb903c16-5736-4e02-89cc-5e8403e45528', 'general_lines', NULL, 'What does ''premium'' mean in insurance terminology?', '¿Qué significa ''prima'' en terminología de seguros?', '["The amount paid for coverage", "The maximum coverage limit", "The deductible amount", "The claim payout"]', '["La cantidad pagada por la cobertura", "El límite máximo de cobertura", "El monto del deducible", "El pago de la reclamación"]', 0, 'A premium is the amount of money an individual or business pays for an insurance policy, typically on a monthly or annual basis.', 'Una prima es la cantidad de dinero que un individuo o empresa paga por una póliza de seguro, generalmente de forma mensual o anual.', true, '2026-01-14 16:50:01.919359', '2026-01-14 16:50:01.919359') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ed2386ca-d108-409a-8d03-99059ef343f5', 'general_lines', NULL, 'What is a symbol system in commercial auto coverage?', '¿Qué es un sistema de símbolos en la cobertura de auto comercial?', '["A company logo", "A numbering system that identifies which vehicles are covered for each type of coverage", "A premium calculation", "A claim form"]', '["Un logotipo de empresa", "Un sistema de numeración que identifica qué vehículos están cubiertos para cada tipo de cobertura", "Un cálculo de prima", "Un formulario de reclamo"]', 1, 'The symbol system uses numbers (1-9) to identify which vehicles are covered for liability, physical damage, and other coverages in the policy.', 'El sistema de símbolos usa números (1-9) para identificar qué vehículos están cubiertos para responsabilidad, daños físicos y otras coberturas en la póliza.', true, '2026-01-14 23:16:55.563603', '2026-01-14 23:16:55.563603') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ee2f9fce-3209-4052-96b0-c20a771b8655', 'general_lines', NULL, 'What is the role of an insurance underwriter?', '¿Cuál es el rol de un suscriptor de seguros?', '["To sell insurance policies", "To evaluate risks and determine policy terms and premiums", "To process claims", "To manage customer complaints"]', '["Vender pólizas de seguro", "Evaluar riesgos y determinar los términos y primas de la póliza", "Procesar reclamaciones", "Gestionar quejas de clientes"]', 1, 'An underwriter assesses the risk of insuring a person or asset and determines whether to offer coverage and at what premium.', 'Un suscriptor evalúa el riesgo de asegurar a una persona o activo y determina si ofrecer cobertura y a qué prima.', true, '2026-01-14 16:50:01.914071', '2026-01-14 16:50:01.914071') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('ee625aff-ec84-423a-b1f8-4b456595bea2', 'general_lines', NULL, 'What is subrogation in insurance?', '¿Qué es la subrogación en seguros?', '["A type of policy", "The insurer''s right to recover from a third party after paying a claim", "A premium payment method", "A type of endorsement"]', '["Un tipo de póliza", "El derecho del asegurador de recuperar de un tercero después de pagar un reclamo", "Un método de pago de prima", "Un tipo de endoso"]', 1, 'Subrogation is the insurer''s legal right to pursue a third party who caused the loss after the insurer has paid the claim.', 'La subrogación es el derecho legal del asegurador de perseguir a un tercero que causó la pérdida después de que el asegurador haya pagado el reclamo.', true, '2026-01-14 23:10:18.136186', '2026-01-14 23:10:18.136186') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f14dac2b-c499-4161-99a0-6e7468ae96c0', 'general_lines', NULL, 'What is uninsured/underinsured motorist coverage?', '¿Qué es la cobertura de motorista sin seguro/con seguro insuficiente?', '["Coverage for uninsured vehicles", "Coverage protecting the insured when injured by a driver with no or inadequate insurance", "Property coverage", "Life insurance"]', '["Cobertura para vehículos sin seguro", "Cobertura que protege al asegurado cuando es lesionado por un conductor sin seguro o con seguro inadecuado", "Cobertura de propiedad", "Seguro de vida"]', 1, 'UM/UIM coverage pays for injuries to the insured when the at-fault driver has no insurance or insufficient coverage to pay for damages.', 'La cobertura UM/UIM paga por lesiones al asegurado cuando el conductor culpable no tiene seguro o tiene cobertura insuficiente para pagar los daños.', true, '2026-01-14 23:16:55.57349', '2026-01-14 23:16:55.57349') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f1dc7c09-6067-4bd4-bae6-062e091065cc', 'general_lines', NULL, 'What is medical payments coverage in a CGL policy?', '¿Qué es la cobertura de pagos médicos en una póliza CGL?', '["Coverage for employee injuries", "Coverage paying medical expenses for injuries to non-employees on the premises regardless of fault", "Health insurance", "Life insurance"]', '["Cobertura para lesiones de empleados", "Cobertura que paga gastos médicos para lesiones a no empleados en las instalaciones sin importar la culpa", "Seguro de salud", "Seguro de vida"]', 1, 'Medical payments coverage pays medical expenses for injuries to third parties on the insured''s premises, regardless of fault, up to the policy limit.', 'La cobertura de pagos médicos paga gastos médicos para lesiones a terceros en las instalaciones del asegurado, sin importar la culpa, hasta el límite de la póliza.', true, '2026-01-14 23:13:37.399545', '2026-01-14 23:13:37.399545') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f69e72ed-d0c2-47c2-8b0a-b596619176b6', 'general_lines', NULL, 'What is a license and permit bond?', '¿Qué es una fianza de licencia y permiso?', '["A performance bond", "A bond required by government for licensees to ensure compliance with regulations", "A payment bond", "A fidelity bond"]', '["Una fianza de cumplimiento", "Una fianza requerida por el gobierno para licenciatarios para asegurar cumplimiento con regulaciones", "Una fianza de pago", "Una fianza de fidelidad"]', 1, 'License and permit bonds are required by government agencies and guarantee that licensees will comply with laws and regulations in their business activities.', 'Las fianzas de licencia y permiso son requeridas por agencias gubernamentales y garantizan que los licenciatarios cumplirán con leyes y regulaciones en sus actividades comerciales.', true, '2026-01-14 23:16:55.513451', '2026-01-14 23:16:55.513451') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('f90bf8a2-7a92-4b3f-8750-31852c2ce977', 'general_lines', NULL, 'What is the Texas Windstorm Insurance Association (TWIA)?', '¿Qué es la Asociación de Seguros contra Tormentas de Viento de Texas (TWIA)?', '["A private insurer", "A state-created pool providing wind and hail coverage in designated coastal areas", "A federal program", "A liability insurer"]', '["Un asegurador privado", "Un fondo creado por el estado que proporciona cobertura de viento y granizo en áreas costeras designadas", "Un programa federal", "Un asegurador de responsabilidad"]', 1, 'TWIA is a residual market mechanism created by the Texas Legislature to provide wind and hail coverage in designated catastrophe areas along the coast.', 'TWIA es un mecanismo de mercado residual creado por la Legislatura de Texas para proporcionar cobertura de viento y granizo en áreas de catástrofe designadas a lo largo de la costa.', true, '2026-01-14 23:13:37.304452', '2026-01-14 23:13:37.304452') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('fc639ea8-71e5-4baa-8985-18fb8913b8f0', 'general_lines', NULL, 'What is a loss ratio?', '¿Qué es un índice de pérdidas?', '["A claims processing speed", "The ratio of claims paid to premiums earned", "A deductible calculation", "A coverage limit"]', '["Una velocidad de procesamiento de reclamos", "La proporción de reclamos pagados a primas ganadas", "Un cálculo de deducible", "Un límite de cobertura"]', 1, 'The loss ratio is calculated by dividing incurred losses by earned premiums, measuring the percentage of premiums used to pay claims.', 'El índice de pérdidas se calcula dividiendo las pérdidas incurridas entre las primas ganadas, midiendo el porcentaje de primas usadas para pagar reclamos.', true, '2026-01-14 23:16:55.585304', '2026-01-14 23:16:55.585304') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('fdec2606-4724-4f21-8856-390c8ab9063e', 'general_lines', NULL, 'What is the duty to cooperate?', '¿Qué es el deber de cooperar?', '["A sales requirement", "The insured''s obligation to assist the insurer in investigating and defending claims", "A premium payment duty", "An agent''s obligation"]', '["Un requisito de ventas", "La obligación del asegurado de asistir al asegurador en investigar y defender reclamos", "Un deber de pago de prima", "Una obligación del agente"]', 1, 'The duty to cooperate requires the insured to assist the insurer in claim investigation, provide documents, and cooperate in legal defense.', 'El deber de cooperar requiere que el asegurado asista al asegurador en la investigación de reclamos, proporcione documentos y coopere en la defensa legal.', true, '2026-01-14 23:23:20.994236', '2026-01-14 23:23:20.994236') ON CONFLICT (id) DO NOTHING;
INSERT INTO questions (id, category, topic, question_text_en, question_text_es, options_en, options_es, correct_answer, explanation_en, explanation_es, is_active, created_at, updated_at) VALUES ('feefaf53-7954-4a3c-a94c-b47580d73c2e', 'general_lines', NULL, 'What is the purpose of a manuscript policy?', '¿Cuál es el propósito de una póliza manuscrita?', '["A standard form policy", "A customized policy written for unique risks", "A life insurance policy", "An auto policy"]', '["Una póliza de formulario estándar", "Una póliza personalizada escrita para riesgos únicos", "Una póliza de seguro de vida", "Una póliza de auto"]', 1, 'A manuscript policy is a customized policy specifically drafted to address unique coverage needs that standard forms don''t adequately cover.', 'Una póliza manuscrita es una póliza personalizada específicamente redactada para abordar necesidades de cobertura únicas que los formularios estándar no cubren adecuadamente.', true, '2026-01-14 23:16:55.473509', '2026-01-14 23:16:55.473509') ON CONFLICT (id) DO NOTHING;
